result:
.yyy{
  display: flex;
  .yyy_l{
    // width: 200px;
    // height: 100px;
    // background: red;



    position: relative;
    padding-top: 15px;

    background-color: #cfe6f9;
    border-radius: 5px;


    .xt-layout-has-sider{
      width: 200px;
      min-width: 200px;
      max-width: 200px;
      -webkit-box-flex: 0;
      -ms-flex: 0 0 200px;
      flex: 0 0 200px;
      -webkit-transition: all 0.3s;
      transition: all 0.3s;
    }
    .xt-layout-none-sider{
      width: 0px;
      min-width: 0px;
      max-width: 0px;
      -webkit-box-flex: 0;
      -ms-flex: 0 0 0px;
      flex: 0 0 0px;
      -webkit-transition: all 0.3s;
      transition: all 0.3s;
    }
    .xt-layout-sider{
      height: 100%;
      position: relative;
    }
    .layout-sider-btn{
      position: absolute;
      width: 12px;
      height: 87px;
      top: 50%;
      right: -12px;
      -webkit-transform: translateY(-50%);
      transform: translateY(-50%);
      background-color: #909399;
      color: #fff;
      cursor: pointer;
      border-radius: 0 5px 5px 0;
      display: -webkit-box;
      display: -ms-flexbox;
      display: flex;
      -webkit-box-align: center;
      -ms-flex-align: center;
      align-items: center;
      -webkit-box-pack: center;
      -ms-flex-pack: center;
      justify-content: center;
    }
    .el-scrollbar {
        overflow: hidden;
        position: relative;
    }

    .el-tree {
        background: transparent;
        color: #46506d;
    }
  }
  .yyy_r{
    padding-left: 20px;
    width: 10px;
    flex: 1;
  }
}

::v-deep .dates {
  .el-range__icon{
    line-height: 25px;
  }
}
::v-deep .list_btn{
  padding: 9px 5px !important;
}
::v-deep .btn_red{
  color: red;
}
.title_line{

  position: relative;
  padding-left: 15px;
  font-size: 15px;
  font-weight: bold;
  height: 20px;
  &::before{
    content: '';
    position: absolute;
    left: 0px;
    width: 0px;
    height: 100%;
    border-left: 4px solid;
    z-index: 9;
    margin-right: 4px;
    color: #409EFF;
  }


}
